add_filter( 'woocommerce_checkout_fields', 'perfectpixel_confirm_email_field', 9999 );
add_action( 'woocommerce_checkout_process', 'perfectpixel_confirm_email_validate' );

function perfectpixel_confirm_email_field( $fields ) {
	if ( ! isset( $fields['billing']['billing_email'] ) || is_user_logged_in() ) {
		return $fields;
	}
	// The key has no "billing_" prefix, so WooCommerce does not save it to the order.
	$fields['billing']['perfectpixel_confirm_email'] = array(
		'label'        => '{{confirm_email_label}}',
		'type'         => 'email',
		'required'     => true,
		'class'        => array( 'form-row-wide' ),
		'autocomplete' => 'off',
		'priority'     => (int) ( $fields['billing']['billing_email']['priority'] ?? 110 ) + 1,
	);
	return $fields;
}

function perfectpixel_confirm_email_validate() {
	if ( is_user_logged_in() || ! isset( $_POST['perfectpixel_confirm_email'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		return;
	}
	$email   = strtolower( trim( sanitize_email( wp_unslash( $_POST['billing_email'] ?? '' ) ) ) ); // phpcs:ignore WordPress.Security.NonceVerification
	$confirm = strtolower( trim( sanitize_email( wp_unslash( $_POST['perfectpixel_confirm_email'] ) ) ) ); // phpcs:ignore WordPress.Security.NonceVerification
	if ( '' !== $confirm && $email !== $confirm ) {
		wc_add_notice( esc_html( '{{confirm_email_error}}' ), 'error' );
	}
}
